1	package com.example.starter.damage.service;
2	
3	import com.example.starter.damage.api.ApiException;
4	import com.example.starter.damage.domain.CaseStatus;
5	import com.example.starter.damage.domain.Determination;
6	import com.example.starter.damage.dto.Requests.ApprovalRequest;
7	import com.example.starter.damage.dto.Requests.CloseRequest;
8	import com.example.starter.damage.dto.Requests.CompletionRequest;
9	import com.example.starter.damage.dto.Requests.EstimateRequest;
10	import com.example.starter.damage.dto.Requests.PhotoRequest;
11	import com.example.starter.damage.dto.Requests.RegisterRequest;
12	import com.example.starter.damage.dto.Requests.ReinspectionRequest;
13	import com.example.starter.damage.dto.Requests.SurveyRequest;
14	import com.example.starter.damage.dto.Views.ApprovalView;
15	import com.example.starter.damage.dto.Views.CaseDetailView;
16	import com.example.starter.damage.dto.Views.CaseView;
17	import com.example.starter.damage.dto.Views.CompletionView;
18	import com.example.starter.damage.dto.Views.EstimateView;
19	import com.example.starter.damage.dto.Views.PhotoResult;
20	import com.example.starter.damage.store.DamageCaseRepository;
21	import com.example.starter.damage.store.DamageCaseRepository.CaseRow;
22	import com.example.starter.damage.store.DamageFlowRepository;
23	import org.springframework.dao.DuplicateKeyException;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.annotation.Transactional;
26	
27	import java.math.BigDecimal;
28	import java.time.Clock;
29	import java.time.LocalDate;
30	import java.time.LocalDateTime;
31	import java.util.EnumSet;
32	import java.util.Set;
33	
34	/**
35	 * 残损案事务内业务服务：状态机流转、30% 全损阈值、批复 7 个 UTC 自然日有效期、
36	 * 返修一次限制与判定唯一性均在此强制。所有写方法在事务内执行。
37	 */
38	@Service
39	public class DamageCaseTxService {
40	
41	    /** 全损阈值：单项修理费超过箱值 30% 判全损，恰 30% 按修理处理 */
42	    static final BigDecimal TOTAL_LOSS_THRESHOLD = new BigDecimal("0.30");
43	
44	    /** 修理批复有效期：7 个 UTC 自然日，批复日为第 1 日，恰第 7 日完工有效 */
45	    static final long APPROVAL_VALID_DAYS = 7;
46	
47	    private static final Set<CaseStatus> TERMINAL = EnumSet.of(CaseStatus.RELEASED, CaseStatus.TOTAL_LOSS);
48	
49	    private final DamageCaseRepository caseRepository;
50	    private final DamageFlowRepository flowRepository;
51	    private final IdempotencyExecutor idempotency;
52	    private final Clock clock;
53	
54	    public DamageCaseTxService(DamageCaseRepository caseRepository,
55	                               DamageFlowRepository flowRepository,
56	                               IdempotencyExecutor idempotency,
57	                               Clock clock) {
58	        this.caseRepository = caseRepository;
59	        this.flowRepository = flowRepository;
60	        this.idempotency = idempotency;
61	        this.clock = clock;
62	    }
63	
64	    /** 到港登记：同一箱号同时刻只允许一个进行中残损案，由 active_key 唯一索引仲裁 */
65	    @Transactional
66	    public CaseView register(RegisterRequest request) {
67	        LocalDateTime now = LocalDateTime.now(clock);
68	        long caseId;
69	        try {
70	            caseId = caseRepository.insert(request.containerNo(), request.containerValue(), now);
71	        } catch (DuplicateKeyException e) {
72	            throw ApiException.conflict("同一箱号已存在进行中的残损案，仅唯一受理");
73	        }
74	        CaseView view = loadCase(caseId).toView();
75	        idempotency.completeInTransaction(request.requestId(), view);
76	        return view;
77	    }
78	
79	    /** 检验：按合成 IICL 代码登记残损项并区分责任方，仅在 REGISTERED 状态可登记 */
80	    @Transactional
81	    public CaseDetailView survey(long caseId, SurveyRequest request) {
82	        CaseRow row = lockCase(caseId);
83	        requireStatus(row, CaseStatus.REGISTERED, "仅到港登记状态可登记检验残损项");
84	        for (var item : request.items()) {
85	            if (!flowRepository.iiclCodeExists(item.iiclCode())) {
86	                throw ApiException.badRequest("未知 IICL 残损代码: " + item.iiclCode());
87	            }
88	            flowRepository.insertItem(caseId, item.iiclCode(), item.component(),
89	                    item.description(), item.responsibility(), item.repairCost());
90	        }
91	        caseRepository.updateState(caseId, CaseStatus.SURVEYED, row.determination(), LocalDateTime.now(clock));
92	        CaseDetailView view = detail(caseId);
93	        idempotency.completeInTransaction(request.requestId(), view);
94	        return view;
95	    }
96	
97	    /**
98	     * 估价：生成新估价版本，旧版本置 SUPERSEDED；单项修理费超箱值 30% 判全损。
99	     * 批复逾期后须重新估价；批复仍在有效期内时拒绝重复估价。
100	     */
101	    @Transactional
102	    public EstimateView estimate(long caseId, EstimateRequest request) {
103	        CaseRow row = lockCase(caseId);
104	        if (row.status() == CaseStatus.APPROVED) {
105	            ApprovalView active = flowRepository.findActiveApproval(caseId);
106	            LocalDate today = LocalDate.now(clock);
107	            if (active != null && !today.isAfter(active.approvalDate().plusDays(APPROVAL_VALID_DAYS - 1))) {
108	                throw ApiException.conflict("修理批复仍在有效期内，无需重新估价");
109	            }
110	        } else if (row.status() != CaseStatus.SURVEYED && row.status() != CaseStatus.ESTIMATED) {
111	            throw ApiException.conflict("当前状态不允许估价: " + row.status());
112	        }
113	        var items = flowRepository.listItems(caseId);
114	        if (items.isEmpty()) {
115	            throw ApiException.badRequest("残损清单为空，无法估价");
116	        }
117	        BigDecimal threshold = row.containerValue().multiply(TOTAL_LOSS_THRESHOLD);
118	        BigDecimal total = items.stream()
119	                .map(item -> item.repairCost())
120	                .reduce(BigDecimal.ZERO, BigDecimal::add);
121	        Determination determination = items.stream()
122	                .anyMatch(item -> item.repairCost().compareTo(threshold) > 0)
123	                ? Determination.TOTAL_LOSS
124	                : Determination.REPAIR;
125	        flowRepository.supersedeActiveApprovals(caseId);
126	        long estimateId = flowRepository.insertEstimate(caseId, total, determination,
127	                request.requestId(), LocalDateTime.now(clock));
128	        caseRepository.updateState(caseId, CaseStatus.ESTIMATED, determination, LocalDateTime.now(clock));
129	        EstimateView view = flowRepository.listEstimates(caseId).stream()
130	                .filter(e -> e.id() == estimateId)
131	                .findFirst()
132	                .orElseThrow();
133	        idempotency.completeInTransaction(request.requestId(), view);
134	        return view;
135	    }
136	
137	    /** 修理批复：仅修理判定可批复，全损与修理不得并发成立 */
138	    @Transactional
139	    public ApprovalView approve(long caseId, ApprovalRequest request) {
140	        CaseRow row = lockCase(caseId);
141	        requireStatus(row, CaseStatus.ESTIMATED, "仅已估价状态可批复修理");
142	        if (row.determination() != Determination.REPAIR) {
143	            throw ApiException.conflict("全损案件不得批复修理，判定唯一");
144	        }
145	        EstimateView current = flowRepository.findCurrentEstimate(caseId);
146	        if (current == null) {
147	            throw ApiException.conflict("无有效估价版本，无法批复");
148	        }
149	        LocalDate approvalDate = request.approvalDate() != null ? request.approvalDate() : LocalDate.now(clock);
150	        long approvalId = flowRepository.insertApproval(caseId, current.id(), approvalDate, LocalDateTime.now(clock));
151	        caseRepository.updateState(caseId, CaseStatus.APPROVED, row.determination(), LocalDateTime.now(clock));
152	        ApprovalView view = flowRepository.listApprovals(caseId).stream()
153	                .filter(a -> a.id() == approvalId)
154	                .findFirst()
155	                .orElseThrow();
156	        idempotency.completeInTransaction(request.requestId(), view);
157	        return view;
158	    }
159	
160	    /** 修理（或返修）完工：完工日期须在批复 7 个 UTC 自然日有效期内，恰第 7 日有效 */
161	    @Transactional
162	    public CompletionView completeRepair(long caseId, CompletionRequest request) {
163	        CaseRow row = lockCase(caseId);
164	        if (row.status() != CaseStatus.APPROVED && row.status() != CaseStatus.REWORK) {
165	            throw ApiException.conflict("当前状态不允许登记完工: " + row.status());
166	        }
167	        ApprovalView active = flowRepository.findActiveApproval(caseId);
168	        if (active == null) {
169	            throw ApiException.conflict("无有效修理批复，无法登记完工");
170	        }
171	        LocalDate completionDate = request.completionDate() != null ? request.completionDate() : LocalDate.now(clock);
172	        LocalDate lastValidDay = active.approvalDate().plusDays(APPROVAL_VALID_DAYS - 1);
173	        if (completionDate.isAfter(lastValidDay)) {
174	            throw ApiException.conflict("修理批复已逾期（有效期 7 个自然日），须重新估价");
175	        }
176	        boolean rework = row.status() == CaseStatus.REWORK;
177	        flowRepository.insertCompletion(caseId, completionDate, rework, LocalDateTime.now(clock));
178	        caseRepository.updateState(caseId, CaseStatus.REPAIR_DONE, row.determination(),
179	                row.reworkCount(), LocalDateTime.now(clock));
180	        CompletionView view = flowRepository.listCompletions(caseId).stream()
181	                .reduce((first, second) -> second)
182	                .orElseThrow();
183	        idempotency.completeInTransaction(request.requestId(), view);
184	        return view;
185	    }
186	
187	    /** 复检：不合格仅允许返修一次，返修后仍不合格转全损评估 */
188	    @Transactional
189	    public CaseView reinspect(long caseId, ReinspectionRequest request) {
190	        CaseRow row = lockCase(caseId);
191	        requireStatus(row, CaseStatus.REPAIR_DONE, "仅修理完工后可复检");
192	        flowRepository.insertReinspection(caseId, request.passed(), LocalDateTime.now(clock));
193	        LocalDateTime now = LocalDateTime.now(clock);
194	        if (request.passed()) {
195	            caseRepository.updateState(caseId, CaseStatus.REPAIR_PASSED, row.determination(),
196	                    row.reworkCount(), now);
197	        } else if (row.reworkCount() == 0) {
198	            caseRepository.updateState(caseId, CaseStatus.REWORK, row.determination(), 1, now);
199	        } else {
200	            flowRepository.supersedeActiveApprovals(caseId);
201	            caseRepository.updateState(caseId, CaseStatus.TOTAL_LOSS_PENDING, Determination.TOTAL_LOSS,
202	                    row.reworkCount(), now);
203	        }
204	        CaseView view = loadCase(caseId).toView();
205	        idempotency.completeInTransaction(request.requestId(), view);
206	        return view;
207	    }
208	
209	    /**
210	     * 结案：修理放行与案件关闭在同一事务内完成；结案为终态，重复结案返回幂等成功。
211	     */
212	    @Transactional
213	    public CaseView close(long caseId, CloseRequest request) {
214	        CaseRow row = lockCase(caseId);
215	        LocalDateTime now = LocalDateTime.now(clock);
216	        if (TERMINAL.contains(row.status())) {
217	            CaseView view = row.toView();
218	            idempotency.completeInTransaction(request.requestId(), view);
219	            return view;
220	        }
221	        if (row.status() == CaseStatus.REPAIR_PASSED) {
222	            caseRepository.close(caseId, CaseStatus.RELEASED, now);
223	        } else if (row.determination() == Determination.TOTAL_LOSS
224	                && (row.status() == CaseStatus.ESTIMATED || row.status() == CaseStatus.TOTAL_LOSS_PENDING)) {
225	            caseRepository.close(caseId, CaseStatus.TOTAL_LOSS, now);
226	        } else {
227	            throw ApiException.conflict("当前状态不允许结案: " + row.status());
228	        }
229	        CaseView view = loadCase(caseId).toView();
230	        idempotency.completeInTransaction(request.requestId(), view);
231	        return view;
232	    }
233	
234	    /** 检验照片：结案后迟到照片只记迟到事件，不改变案件状态 */
235	    @Transactional
236	    public PhotoResult photo(long caseId, PhotoRequest request) {
237	        CaseRow row = lockCase(caseId);
238	        LocalDateTime now = LocalDateTime.now(clock);
239	        if (TERMINAL.contains(row.status())) {
240	            flowRepository.insertEvent(caseId, "LATE_PHOTO", request.photoRef(), now);
241	            return new PhotoResult("LATE_RECORDED");
242	        }
243	        flowRepository.insertEvent(caseId, "PHOTO", request.photoRef(), now);
244	        return new PhotoResult("ATTACHED");
245	    }
246	
247	    /** 案件全量明细：残损清单、估价版本与修理链均可复算 */
248	    @Transactional(readOnly = true)
249	    public CaseDetailView detail(long caseId) {
250	        CaseRow row = caseRepository.findById(caseId)
251	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
252	        return new CaseDetailView(
253	                row.toView(),
254	                flowRepository.listItems(caseId),
255	                flowRepository.listEstimates(caseId),
256	                flowRepository.listApprovals(caseId),
257	                flowRepository.listCompletions(caseId),
258	                flowRepository.listReinspections(caseId),
259	                flowRepository.listEvents(caseId));
260	    }
261	
262	    private CaseRow lockCase(long caseId) {
263	        return caseRepository.findByIdForUpdate(caseId)
264	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
265	    }
266	
267	    private CaseRow loadCase(long caseId) {
268	        return caseRepository.findById(caseId)
269	                .orElseThrow(() -> ApiException.notFound("残损案不存在: " + caseId));
270	    }
271	
272	    private void requireStatus(CaseRow row, CaseStatus expected, String message) {
273	        if (row.status() != expected) {
274	            throw ApiException.conflict(message + "，当前状态: " + row.status());
275	        }
276	    }
277	}
